function sumTo(limit) {
  let total = 0;
  for (let number = 1; number <= limit; number += 1) total += number;
  return total;
}

function sumByStep(start, end, step) {
  let total = 0;
  for (let number = start; number <= end; number += step) total += number;
  return total;
}
